import{_ as i,C as a,o as s,c as l,j as t,a as o,E as r,a6 as c}from"./chunks/framework.CD0vXS2f.js";const x=JSON.parse('{"title":"05 · Controlled 429 Fault Injection & G1–G12 Release Standard","description":"Pre-production verification protocol for testing APIM Retry-After circuit breakers, SSE streaming non-buffering, and the 12-point Gateway Readiness Standard (G1–G12).","frontmatter":{"title":"05 · Controlled 429 Fault Injection & G1–G12 Release Standard","description":"Pre-production verification protocol for testing APIM Retry-After circuit breakers, SSE streaming non-buffering, and the 12-point Gateway Readiness Standard (G1–G12)."},"headers":[],"relativePath":"playbooks/apim-gateway/05-validation-chaos-testing.md","filePath":"playbooks/apim-gateway/05-validation-chaos-testing.md","lastUpdated":1795280666087}'),g={name:"playbooks/apim-gateway/05-validation-chaos-testing.md"};function p(f,e,u,y,h,m){const n=a("PlaybookMeta"),d=a("PageBrief");return s(),l("div",null,[e[0]||(e[0]=t("h1",{id:"_05-·-controlled-429-fault-injection-g1–g12-release-standard",tabindex:"-1"},[o("05 · Controlled 429 Fault Injection & "),t("code",null,"G1–G12"),o(" Release Standard "),t("a",{class:"header-anchor",href:"#_05-·-controlled-429-fault-injection-g1–g12-release-standard","aria-label":'Permalink to "05 · Controlled 429 Fault Injection & `G1–G12` Release Standard"'},"​")],-1)),r(n,{track:"02 · Multi-Backend Foundry APIM AI Gateway & Governance",verified:"2026-11-19 PST",status:"Live v2.0",printable:""}),r(d,{stage:"validate",readTime:"4 min read",problem:"Unverified failover policies frequently fail in production due to missing RBAC roles on the secondary PAYG resource, buffered SSE streams, or snapshot version mismatches.",takeaway:"Execute the 4-step fault-injection protocol in staging and require all 12 G1–G12 gateway controls before routing production traffic.",csaUse:"Run Steps 1–4 during Week 2/3 staging sign-off and paste G1–G12 into the gateway infrastructure pull request."}),e[1]||(e[1]=c('<h2 id="_0-offline-policy-xml-preflight" tabindex="-1">0. Offline Policy XML Preflight <a class="header-anchor" href="#_0-offline-policy-xml-preflight" aria-label="Permalink to &quot;0. Offline Policy XML Preflight&quot;">​</a></h2><p>APIM policy expressions use C# inside XML attributes or element text (<a href="https://learn.microsoft.com/en-us/azure/api-management/api-management-policy-expressions" target="_blank" rel="noreferrer">Microsoft Learn policy expression syntax</a>) <span class="ev-badge ev-m">[M]</span>. Encode embedded attribute quotes as <code>&amp;quot;</code> and C# generic brackets as <code>&amp;lt;</code> / <code>&amp;gt;</code>; XML parsing restores the original expression.</p><p>Run <code>npm run verify</code> before staging: its <code>check:apim</code> gate parses both the downloadable policy and the built Studio&#39;s default copyable XML, rejecting malformed expressions, missing artifacts, missing rendered policy output, and violations of the static per-attempt spillover body contract <span class="ev-badge ev-arch">[Arch]</span>.</p><p>For <code>G8</code>, the same gate requires every visible backend <code>forward-request</code> to set literal <code>buffer-response=&quot;false&quot;</code>. Microsoft Learn documents that this attribute defaults to <code>true</code> and recommends <code>false</code> for <a href="https://learn.microsoft.com/en-us/azure/api-management/forward-request-policy#attributes" target="_blank" rel="noreferrer">immediate SSE chunk forwarding</a>; its <a href="https://learn.microsoft.com/en-us/azure/api-management/how-to-server-sent-events#guidelines-for-sse" target="_blank" rel="noreferrer">SSE guidance</a> also warns against response-buffering policies, body logging, and response caching <span class="ev-badge ev-m">[M]</span>. The local regression guard rejects outbound <code>set-body</code>, <code>validate-content</code>, <code>json-to-xml</code>, <code>xml-to-json</code>, <code>find-and-replace</code>, <code>xsl-transform</code>, and <code>cache-store</code>, including nested branches, plus direct <code>context.Response.Body</code> access in outbound expression text or attributes. Header/status access and inbound PTU request-body rewriting remain allowed <span class="ev-badge ev-arch">[Arch]</span>.</p><p>These are static checks, not APIM policy schema validation, C# compilation, or a complete streaming proof. They do not resolve inherited <code>&lt;base /&gt;</code>/policy fragments, C# aliases or indirect body access, diagnostic body logging, or alternate Studio settings (including deliberately disabling SSE). Review the effective policy and diagnostics, then run the staging probes below; offline success does not establish the TTFT target or safe mid-stream retry behavior <span class="ev-badge ev-val">[Validate]</span>.</p><h2 id="_1-four-step-staging-fault-injection-protocol-validate" tabindex="-1">1. Four-Step Staging Fault-Injection Protocol <code>[Validate]</code> <a class="header-anchor" href="#_1-four-step-staging-fault-injection-protocol-validate" aria-label="Permalink to &quot;1. Four-Step Staging Fault-Injection Protocol `[Validate]`&quot;">​</a></h2><ol><li><strong>Step 1 — Synthetic <code>429 Retry-After</code> Trip Test:</strong> Temporarily route Priority-1 to a mock APIM endpoint (or minimal 15-PTU canary deployment under synthetic burst) returning <code>HTTP 429</code> with <code>Retry-After: 25</code>. Verify: <ul><li>Call #1 transparently retries inside <code>&lt;backend&gt;</code> onto Priority-2 Standard PAYG and returns <code>HTTP 200</code> (<code>x-gateway-routed-sku: standard-spillover</code>).</li><li>Calls #2..N during the next <code>25s</code> route directly to Priority-2 in <code>&lt;5ms</code> gateway overhead without hitting Priority-1.</li><li>After <code>25s</code>, traffic automatically heals back to Priority-1 PTU-M.</li></ul></li><li><strong>Step 2 — Unbuffered SSE TTFT Parity Probe:</strong> Send a 4,000-token <code>stream: true</code> request through APIM and directly to the VNet Foundry endpoint. Confirm gateway TTFT overhead is <code>&lt;35ms</code> (if TTFT jumps to full completion time, an outbound body-inspection policy is buffering the stream).</li><li><strong>Step 3 — SKU Breakpoint Compatibility Check:</strong> Send a payload containing <code>prompt_cache_breakpoint</code> and <code>prompt_cache_options</code> through a GPT-5.6 PTU-M route; confirm HTTP <code>200</code> and non-zero <code>cached_tokens</code> on Pass 2.</li><li><strong>Step 4 — FinOps Header &amp; Cache-Key Isolation Probe:</strong> Send 10 sequential calls with distinct <code>x-cost-center</code> values (<code>CC-1001</code>..<code>CC-1010</code>) but the same sharded <code>prompt_cache_key</code>. Confirm Pass 2–10 hit the prefix cache (<code>≥80%</code> hit rate) while all 10 <code>CostCenter</code> values appear in App Insights metrics.</li></ol><hr><h2 id="_2-the-12-point-ai-gateway-readiness-standard-g1–g12-agree" tabindex="-1">2. The 12-Point AI Gateway Readiness Standard (<code>G1–G12</code>) <code>[Agree]</code> <a class="header-anchor" href="#_2-the-12-point-ai-gateway-readiness-standard-g1–g12-agree" aria-label="Permalink to &quot;2. The 12-Point AI Gateway Readiness Standard (`G1–G12`) `[Agree]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Gate ID</th><th style="text-align:left;">Category</th><th style="text-align:left;">Verification Requirement</th><th style="text-align:left;">Target Pass Bar</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>G1</code></strong></td><td style="text-align:left;">Identity &amp; Zero Keys</td><td style="text-align:left;">Upstream Foundry accounts enforce <code>disableLocalAuth: true</code>; APIM authenticates via Managed Identity (<code>Cognitive Services OpenAI User</code>) <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><code>100%</code> keyless upstream</td></tr><tr><td style="text-align:left;"><strong><code>G2</code></strong></td><td style="text-align:left;">Caller Auth</td><td style="text-align:left;">Production callers authenticate to APIM via <code>&lt;validate-azure-ad-token&gt;</code> (Entra ID app roles) over private VNet / Private Link <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;">Enforced in prod</td></tr><tr><td style="text-align:left;"><strong><code>G3</code></strong></td><td style="text-align:left;">Spillover Pool</td><td style="text-align:left;">Native APIM Backend Pool pairs Priority-1 <code>PTU-M</code> with Priority-2 <code>Standard PAYG</code> inside the <strong>same Data Zone / residency boundary</strong> <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Configured in IaC</td></tr><tr><td style="text-align:left;"><strong><code>G4</code></strong></td><td style="text-align:left;">Snapshot Parity</td><td style="text-align:left;">Priority-1 and Priority-2 deployments pin the <strong>exact same model version snapshot</strong> (e.g., <code>2026-09-29</code>).</td><td style="text-align:left;">Exact string match</td></tr><tr><td style="text-align:left;"><strong><code>G5</code></strong></td><td style="text-align:left;">Circuit Breaker</td><td style="text-align:left;">Priority-1 backend configures <code>circuitBreaker</code> for <code>429</code> and <code>500–599</code> with <code>acceptRetryAfter: true</code> <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Verified via <code>429</code> injection</td></tr><tr><td style="text-align:left;"><strong><code>G6</code></strong></td><td style="text-align:left;">SKU Payload Guard</td><td style="text-align:left;">Routes targeting <code>GPT-5.6 PTU-M</code> strip unsupported <code>prompt_cache_options</code> / <code>prompt_cache_breakpoint</code> while preserving <code>prompt_cache_key</code> <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Zero HTTP <code>400</code>s</td></tr><tr><td style="text-align:left;"><strong><code>G7</code></strong></td><td style="text-align:left;">Cache Locality</td><td style="text-align:left;">Load balancing never randomly sprays a single low-RPM <code>prompt_cache_key</code> shard across multiple active-active accounts.</td><td style="text-align:left;"><code>≥80%</code> repeat hit rate</td></tr><tr><td style="text-align:left;"><strong><code>G8</code></strong></td><td style="text-align:left;">Unbuffered SSE</td><td style="text-align:left;">Streaming routes set <code>buffer-response=&quot;false&quot;</code> and exclude outbound body-reading policies <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><code>&lt;35ms</code> gateway TTFT delta</td></tr><tr><td style="text-align:left;"><strong><code>G9</code></strong></td><td style="text-align:left;">Timeout Alignment</td><td style="text-align:left;"><code>&lt;forward-request timeout=&quot;...&quot;&gt;</code> exceeds p99 reasoning completion latency (<code>≥120–180s</code>).</td><td style="text-align:left;">Zero premature <code>504</code>s</td></tr><tr><td style="text-align:left;"><strong><code>G10</code></strong></td><td style="text-align:left;">Out-of-Band FinOps</td><td style="text-align:left;"><code>x-cost-center</code> / <code>x-practice-id</code> extracted into telemetry dimensions and stripped before upstream forwarding <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;">Verified in App Insights</td></tr><tr><td style="text-align:left;"><strong><code>G11</code></strong></td><td style="text-align:left;">Noisy-Neighbor Cap</td><td style="text-align:left;"><code>&lt;azure-openai-token-limit&gt;</code> enforces per-tenant / per-app TPM budgets below total pool exhaustion <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Policy active</td></tr><tr><td style="text-align:left;"><strong><code>G12</code></strong></td><td style="text-align:left;">Spillover Alerting</td><td style="text-align:left;">Azure Monitor alert fires if Priority-2 Standard PAYG spillover exceeds <code>15%</code> of non-surge weekly traffic (signaling base PTU under-sizing) <span class="ev-badge ev-agree">[Agree]</span>.</td><td style="text-align:left;">Alert rule deployed</td></tr></tbody></table>',10))])}const v=i(g,[["render",p]]);export{x as __pageData,v as default};
